2	
3	import java.util.List;
4	
5	import net.officefloor.plugin.variable.Out;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerFieldsException;
8	import org.springframework.web.bind.annotation.RequestBody;
9	
10	/**
11	 * First step of {@code POST /api/owners}. Normalizes the telephone by stripping every
12	 * non-digit character, then requires exactly ten digits; the normalized value is written
13	 * back onto the body so the persisted and returned {@code telephone} is those ten digits.
14	 * A telephone that is not exactly ten digits after stripping throws
15	 * {@link InvalidOwnerFieldsException} for a 400. Because it must run before the DTO's
16	 * digits-only pattern check would reject the raw input, this is the pipeline's sole
17	 * {@code @RequestBody} binding; the normalized body is published for {@link ValidateOwnerFields}.
18	 */
19	public class NormalizeOwnerTelephone {
20	
21	    private static final int REQUIRED_DIGITS = 10;
22	
23	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> normalized)
24	            throws InvalidOwnerFieldsException {
25	
26	        String digits = OwnerTelephone.digits(request.getTelephone());
27	        if (digits.length() != REQUIRED_DIGITS) {
28	            throw new InvalidOwnerFieldsException(List.of("telephone"));
29	        }
30	
31	        request.setTelephone(digits);
32	        normalized.set(request);
33	    }
34	}
